import './style.css';

type Project = { id: string; name: string; status: string; ratio: string; style: string; theme: string; createdAt: string; scenes: number; characters: number; locations: number; props: number };
type DramaAsset = { id: string; drama_id?: string; type: 'character' | 'scene' | 'prop' | string; name: string; prompt: string; image_url?: string | null; status: string; created_at?: string; updated_at?: string };
type DramaEpisode = { id: string; title: string; sort_order?: number };
type DramaShot = { id: string; episode_id?: string; episode_name?: string; shot_index?: number; title: string; original_text: string; prompt: string; status: string; historical_videos?: { id?: string; url?: string | null; generated_at?: string; task_id?: string }[] };
type ApiProject = { id: string; name: string; script?: string; status: string; ratio: string; style: string; theme: string; language_model?: string; multimodal_model?: string; video_model?: string; created_at: string; updated_at?: string; episodes?: DramaEpisode[]; shots?: DramaShot[]; assets?: DramaAsset[]; historical_videos?: { shot_id?: string; url?: string | null; generated_at?: string }[]; tasks?: unknown[] };
type GameNode = { id: string; node_type: string; title: string; original_text: string; prompt: string; video_url?: string | null; duration_seconds: number; status: string; position_x: number; position_y: number; video_history?: { url?: string | null; generated_at?: string }[] };
type GameEdge = { id: string; source_node_id: string; target_node_id: string; option_text: string; sort_order: number };
type GameAsset = { id: string; type: string; name: string; prompt: string; image_url?: string | null; status: string };
type Game = { id: string; name: string; script: string; platform: string; style: string; success_ending_count: number; failure_ending_count: number; branch_min: number; branch_max: number; node_duration_min: number; node_duration_max: number; language_model: string; multimodal_model: string; status: string; node_count?: number; asset_count?: number; assets?: GameAsset[]; nodes?: GameNode[]; edges?: GameEdge[]; tasks?: unknown[]; created_at?: string; updated_at?: string };
type ApiGame = Game;
type Locale = 'zh' | 'en';
const API_BASE_URL = (import.meta.env.VITE_API_BASE_URL || 'http://127.0.0.1:8090/api').replace(/\/$/, '');
const copy = {
  workspace: { zh: '创作空间 / AI 应用平台', en: 'WORKSPACE / AI PLATFORM' },
  dramaTitle: { zh: '短剧创作', en: 'Drama Studio' },
  dramaDescription: { zh: '统一管理每一部短剧的角色、场景、道具、剧集与分镜。', en: 'Manage characters, scenes, props, episodes, and shots in one place.' },
  newDrama: { zh: '＋ 新建短剧', en: '＋ New Drama' },
  search: { zh: '搜索短剧名称、模型或配置', en: 'Search dramas, models, or settings' },
  refresh: { zh: '刷新', en: 'Refresh' },
  projects: { zh: '个项目', en: 'projects' },
  ready: { zh: '配置就绪', en: 'Ready' },
  settingsEyebrow: { zh: '系统 / 模型与服务', en: 'SYSTEM / MODELS & SERVICES' },
  settingsTitle: { zh: '配置', en: 'Settings' },
  settingsDescription: { zh: '配置语言模型与多模态模型的调用地址和凭证。', en: 'Configure endpoints and credentials for language and multimodal models.' },
  interactiveGameDescription: { zh: '互动游戏生成工作区即将开放，页面内容稍后补充。', en: 'The interactive game generation workspace is coming soon.' },
  interactiveGameTitle: { zh: '互动游戏生成', en: 'Interactive Game' },
  newGame: { zh: '＋ 创建互动游戏', en: '＋ New Interactive Game' },
  gameSearch: { zh: '搜索游戏名称、平台或风格', en: 'Search games, platforms, or styles' },
  gameProjects: { zh: '个游戏', en: 'games' },
  noGames: { zh: '还没有互动游戏，先创建一个分支视频游戏吧。', en: 'No interactive games yet. Create a branching video game to get started.' },
  gameEditorDescription: { zh: '视频节点、选择边和成功/失败结局组成的互动剧图谱。', en: 'An interactive drama graph made of video nodes, choice edges, and endings.' },
  createGame: { zh: '创建并进入编辑器', en: 'Create and open editor' },
  gameName: { zh: '游戏名称', en: 'Game name' },
  gameScript: { zh: '基础游戏剧本', en: 'Game script' },
  gamePlatform: { zh: '发布平台', en: 'Target platform' },
  gameStyle: { zh: '视觉风格', en: 'Visual style' },
  successEndings: { zh: '成功结局数量', en: 'Success endings' },
  failureEndings: { zh: '失败结局数量', en: 'Failure endings' },
  branchRange: { zh: '每条分支数量', en: 'Choices per node' },
  durationRange: { zh: '节点视频时长（秒）', en: 'Node duration (seconds)' },
  gameScriptHint: { zh: '剧本文本不少于 20 个字，创建后会异步拆解为视频节点和选择边。', en: 'Use at least 20 characters. The graph will be generated asynchronously.' },
  gameCanvas: { zh: '分支编辑画布', en: 'Branch graph canvas' },
  gameAssets: { zh: '基础组成元素', en: 'Base assets' },
  gameNode: { zh: '视频节点', en: 'Video node' },
  gameEdge: { zh: '选择边', en: 'Choice edge' },
  addChoice: { zh: '＋ 新增选项', en: '＋ Add choice' },
  saveChanges: { zh: '保存修改', en: 'Save changes' },
  generateNodeVideo: { zh: '生成节点视频', en: 'Generate node video' },
  deleteChoice: { zh: '删除选项', en: 'Delete choice' },
  reloadGraph: { zh: '刷新图谱', en: 'Refresh graph' },
  emptyDescription: { zh: '这个工作区即将开放，先从短剧生成开始创作吧。', en: 'This workspace is coming soon. Start with drama creation.' },
  enterDrama: { zh: '进入短剧创作', en: 'Open Drama Studio' },
  themeLight: { zh: '切换到浅色模式', en: 'Switch to light mode' },
  themeDark: { zh: '切换到深色模式', en: 'Switch to dark mode' },
  language: { zh: '切换为英文', en: 'Switch to Chinese' },
  collapseSidebar: { zh: '收起侧栏', en: 'Collapse sidebar' },
  expandSidebar: { zh: '展开侧栏', en: 'Expand sidebar' },
  languageModel: { zh: '语言模型', en: 'Language Model' },
  multimodalModel: { zh: '多模态模型', en: 'Multimodal Model' },
  languageModelDescription: { zh: '用于剧本拆解、分镜规划与提示词生成', en: 'For script decomposition, shot planning, and prompt generation' },
  multimodalModelDescription: { zh: '用于生成角色、场景、道具图片和视频', en: 'For character, scene, prop images, and video generation' },
  saveLanguage: { zh: '保存语言模型配置', en: 'Save language model settings' },
  saveMultimodal: { zh: '保存多模态配置', en: 'Save multimodal settings' },
} as const;
let locale: Locale = localStorage.getItem('locale') === 'en' ? 'en' : 'zh';
let darkMode = localStorage.getItem('theme') === 'dark';
let sidebarCollapsed = localStorage.getItem('sidebarCollapsed') === 'true';
function ui(key: keyof typeof copy) { return copy[key][locale]; }
const navLabels: Record<string, { zh: string; en: string }> = {
  home: { zh: '首页', en: 'Home' }, drama: { zh: '短剧生成', en: 'Drama' }, interactiveGame: { zh: '互动游戏生成', en: 'Interactive Game' }, settings: { zh: '配置', en: 'Settings' },
};
function navLabel(key: string) { return navLabels[key]?.[locale] || key; }
function statusLabel(status: string) { return locale === 'en' ? ({ 草稿: 'Draft', 生成中: 'Generating', 生成成功: 'Succeeded', 生成失败: 'Failed' }[status] || status) : status; }
const projects: Project[] = [];
const interactiveGames: Game[] = [];
const nav = [ ['⌂','home'], ['✦','drama'], ['◉','interactiveGame'], ['⚙','settings'] ] as const;
let active = 'drama';
const app = document.querySelector<HTMLDivElement>('#app')!;

function applyTheme() { document.documentElement.dataset.theme = darkMode ? 'dark' : 'light'; }
function render() { applyTheme(); const sidebarLabel = sidebarCollapsed ? ui('expandSidebar') : ui('collapseSidebar'); app.innerHTML = `<div class="shell"><aside class="${sidebarCollapsed?'collapsed':''}"><div class="brand"><span class="brand-mark">✦</span><span>造梦工厂</span></div><div class="nav">${nav.map(([icon,key]) => `<button class="nav-item ${active===key?'active':''}" data-nav="${key}"><i>${icon}</i>${navLabel(key)}${key==='drama'?'<b>Beta</b>':''}</button>`).join('')}</div><div class="aside-bottom"><span class="ready-dot"></span><span>${ui('ready')}</span><div class="aside-tools"><button class="tool-button" id="sidebar-toggle" title="${sidebarLabel}" aria-label="${sidebarLabel}" aria-pressed="${sidebarCollapsed}">${sidebarCollapsed?'›':'‹'}</button><button class="tool-button" id="theme-toggle" title="${darkMode?ui('themeLight'):ui('themeDark')}" aria-label="${darkMode?ui('themeLight'):ui('themeDark')}">${darkMode?'☼':'☾'}</button><button class="tool-button language-button" id="language-toggle" title="${ui('language')}" aria-label="${ui('language')}">文 <small>${locale==='zh'?'EN':'中'}</small></button></div></div></aside><main>${active==='drama'?dramaPage():active==='interactiveGame'?interactiveGamePage():active==='settings'?settingsPage():emptyPage()}</main></div>`; bind(); }
function dramaPage() { return `<header><div><div class="eyebrow">${ui('workspace')}</div><h1>${ui('dramaTitle')}</h1><p>${ui('dramaDescription')}</p></div><button class="primary" id="new-project">${ui('newDrama')}</button></header><section class="toolbar"><div class="search">⌕ <input placeholder="${ui('search')}" /></div><button class="ghost">${ui('refresh')}</button><span class="toolbar-count">${projects.length} ${ui('projects')}</span></section><section class="cards">${projects.map(projectCard).join('')}</section>`; }
function gameEngine(platform: string) { return platform === 'Steam游戏' ? 'Unity' : 'Cocos Creator'; }
function gameFromApi(game: ApiGame): Game { return { ...game, nodes: game.nodes || [], edges: game.edges || [], assets: game.assets || [] }; }
function gameCard(game: Game) { const nodeCount=game.node_count ?? game.nodes?.length ?? 0; const created=game.created_at?.slice(0,16).replace('T',' ')||'刚刚'; return `<article class="project-card game-card" data-game="${game.id}"><div class="card-top"><h2>${escapeHtml(game.name)}</h2><span class="status ${game.status==='生成中'?'running':''}">${game.status==='生成中'?'◌ ':''}${escapeHtml(game.status)}</span><div class="tags"><span>${escapeHtml(game.platform)}</span><span>${escapeHtml(game.style)}</span><span>${gameEngine(game.platform)}</span></div></div><div class="metrics"><div><strong>${nodeCount}</strong><small>${locale==='en'?'Video nodes':'视频节点'}</small></div><div><strong>${game.success_ending_count}</strong><small>${locale==='en'?'Success endings':'成功结局'}</small></div><div><strong>${game.failure_ending_count}</strong><small>${locale==='en'?'Failure endings':'失败结局'}</small></div><div><strong>${game.branch_min}-${game.branch_max}</strong><small>${locale==='en'?'Choices':'每节点选项'}</small></div></div><div class="card-foot">${created}<span>›</span></div></article>`; }
function interactiveGamePage() { return `<header><div><div class="eyebrow">${ui('workspace')}</div><h1>${ui('interactiveGameTitle')}</h1><p>${ui('gameEditorDescription')}</p></div><button class="primary" id="new-game">${ui('newGame')}</button></header><section class="toolbar"><div class="search">⌕ <input placeholder="${ui('gameSearch')}" /></div><button class="ghost" id="refresh-games">${ui('refresh')}</button><span class="toolbar-count">${interactiveGames.length} ${ui('gameProjects')}</span></section>${interactiveGames.length?`<section class="cards">${interactiveGames.map(gameCard).join('')}</section>`:`<div class="empty game-empty"><div class="empty-icon">◉</div><h2>${ui('interactiveGameTitle')}</h2><p>${ui('noGames')}</p><button class="primary" id="new-game-empty">${ui('newGame')}</button></div>`}`; }
async function loadInteractiveGames() { try { const response=await fetch(`${API_BASE_URL}/games`); if(!response.ok) return; const games=await response.json() as ApiGame[]; interactiveGames.splice(0,interactiveGames.length,...games.map(gameFromApi)); if(active==='interactiveGame') render(); } catch(error) { console.warn('互动游戏列表加载失败',error); } }
function openGameModal() { const modal=document.createElement('div'); modal.className='modal-backdrop'; modal.innerHTML=`<div class="modal game-modal"><button class="close">×</button><div class="modal-head"><div class="eyebrow">INTERACTIVE GAME / NEW</div><h2>${ui('newGame')}</h2><p>${ui('gameEditorDescription')}</p></div><label>${ui('gameName')} <em>*</em><input id="game-name" placeholder="例如：雾城抉择" /></label><label>${ui('gameScript')} <em>*</em><textarea id="game-script" rows="7" placeholder="请将互动剧本粘贴到此处，至少 20 个字..."></textarea><div class="hint">${ui('gameScriptHint')}</div><div class="form-grid"><label>${ui('gamePlatform')}<select id="game-platform"><option>微信小游戏</option><option>手机原生游戏</option><option selected>Steam游戏</option></select></label><label>${ui('gameStyle')}<select id="game-style"><option selected>真人风格</option><option>2D动漫</option><option>3D动漫</option></select></label><label>${ui('successEndings')}<input id="game-success" type="number" min="1" value="2" /></label><label>${ui('failureEndings')}<input id="game-failure" type="number" min="1" value="30" /></label><label>${ui('branchRange')}<span class="range-inputs"><input id="game-branch-min" type="number" min="2" max="4" value="2" /><span>～</span><input id="game-branch-max" type="number" min="2" max="4" value="4" /></span></label><label>${ui('durationRange')}<span class="range-inputs"><input id="game-duration-min" type="number" min="1" value="5" /><span>～</span><input id="game-duration-max" type="number" min="1" value="30" /></span></label></div><div class="modal-actions"><button class="ghost close-action">${locale==='en'?'Cancel':'取消'}</button><button class="primary" id="create-game">${ui('createGame')}</button></div></div>`; document.body.append(modal); const close=()=>modal.remove(); modal.querySelectorAll('.close,.close-action').forEach(x=>x.addEventListener('click',close)); modal.querySelector('#create-game')?.addEventListener('click',async()=>{ const value=(id:string)=>((modal.querySelector(`#${id}`) as HTMLInputElement|HTMLSelectElement|HTMLTextAreaElement).value); const name=value('game-name').trim(); const script=value('game-script').trim(); const branchMin=Number(value('game-branch-min')); const branchMax=Number(value('game-branch-max')); const durationMin=Number(value('game-duration-min')); const durationMax=Number(value('game-duration-max')); if(!name||script.length<20){toast('请填写游戏名称，且剧本文本不少于 20 个字');return;} if(branchMin>branchMax||durationMin>durationMax){toast('请检查区间设置');return;} const button=modal.querySelector('#create-game') as HTMLButtonElement; button.disabled=true; button.textContent='创建中…'; try { const response=await fetch(`${API_BASE_URL}/games`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name,script,platform:value('game-platform'),style:value('game-style'),success_ending_count:Number(value('game-success')),failure_ending_count:Number(value('game-failure')),branch_min:branchMin,branch_max:branchMax,node_duration_min:durationMin,node_duration_max:durationMax,language_model:'doubao-seed',multimodal_model:'doubao-seeddream'})}); if(!response.ok) throw new Error(`HTTP ${response.status}`); const game=gameFromApi(await response.json() as ApiGame); const existing=interactiveGames.findIndex(item=>item.id===game.id); if(existing>=0) interactiveGames.splice(existing,1); interactiveGames.unshift(game); close(); await gameDetail(game.id,game); } catch(error) { button.disabled=false; button.textContent=ui('createGame'); toast('创建失败，请确认后端已启动'); console.error(error); } }); }
function gameDetailMarkup(game: Game) { const nodes=game.nodes||[]; const assets=game.assets||[]; return `<div class="game-detail"><button class="back" id="game-back">← ${locale==='en'?'Back to games':'返回游戏列表'}</button><header><div><div class="eyebrow">INTERACTIVE GAME / ${escapeHtml(game.name)}</div><h1>${escapeHtml(game.name)}</h1><p>${ui('gameEditorDescription')}</p><div class="game-meta"><span>${escapeHtml(game.platform)}</span><span>${escapeHtml(game.style)}</span><span>${gameEngine(game.platform)}</span><span>${game.success_ending_count} ${locale==='en'?'success':'成功'} / ${game.failure_ending_count} ${locale==='en'?'failure':'失败'}</span></div></div><div class="header-actions"><button class="ghost" id="game-refresh">${ui('reloadGraph')}</button><button class="primary" id="game-add-edge">${ui('addChoice')}</button></div></header><div class="game-editor-layout"><section class="panel game-assets-panel"><div class="panel-title"><div><h2>${ui('gameAssets')}</h2><p>${assets.length} ${locale==='en'?'assets':'个元素'}</p></div></div><div class="asset-tabs"><button class="tab active">${locale==='en'?'All':'全部'}</button><button class="tab">角色</button><button class="tab">场景</button><button class="tab">道具</button></div>${assets.map(asset=>`<div class="asset-row"><div class="asset-thumb ${asset.type==='scene'?'green':''}">${asset.type==='character'?'♙':asset.type==='scene'?'✦':'◆'}</div><div><b>${escapeHtml(asset.name)}</b><span>${escapeHtml(asset.type)} · ${escapeHtml(asset.status)}</span><p>${escapeHtml(asset.prompt)}</p></div></div>`).join('')}</section><section class="panel game-canvas-panel"><div class="panel-title"><div><h2>${ui('gameCanvas')}</h2><p>${nodes.length} ${locale==='en'?'video nodes':'个视频节点'} · ${game.edges?.length||0} ${locale==='en'?'choices':'条选择边'}</p></div><span class="status ${game.status==='生成中'?'running':''}">${escapeHtml(game.status)}</span></div><div class="game-canvas-wrap" id="game-canvas">${nodes.length?gameGraphMarkup(game):`<div class="game-generating"><div class="empty-icon">◌</div><p>分支图谱生成中，请稍候…</p></div>`}</div></section><section class="panel game-inspector" id="game-inspector"><div class="inspector-empty"><div class="empty-icon">⌁</div><h3>选择一个节点或选项</h3><p>点击中央画布中的视频节点配置视频，点击选项边配置选择文案和目标节点。</p></div></section></div></div>`; }
function gameGraphMarkup(game: Game) { const nodes=game.nodes||[]; const edges=game.edges||[]; const map=new Map(nodes.map(node=>[node.id,node])); const width=Math.max(1320,...nodes.map(node=>node.position_x+230)); const height=Math.max(620,...nodes.map(node=>node.position_y+150)); const lines=edges.map(edge=>{const source=map.get(edge.source_node_id);const target=map.get(edge.target_node_id);if(!source||!target)return '';const x1=source.position_x+180,y1=source.position_y+46,x2=target.position_x,y2=target.position_y+46;const lx=(x1+x2)/2,ly=(y1+y2)/2-12;return `<line class="game-edge-line" data-game-edge="${edge.id}" x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}"></line><button class="game-edge-label" data-game-edge="${edge.id}" style="left:${lx}px;top:${ly}px">${escapeHtml(edge.option_text)}</button>`}).join(''); return `<div class="game-graph" style="width:${width}px;height:${height}px"><svg class="game-edges" width="${width}" height="${height}" viewBox="0 0 ${width} ${height}">${lines.replace(/<button[\s\S]*?<\/button>/g,'')}</svg>${lines.match(/<button[\s\S]*?<\/button>/g)?.join('')||''}${nodes.map(node=>`<button class="game-node ${escapeHtml(node.node_type)}" data-game-node="${node.id}" style="left:${node.position_x}px;top:${node.position_y}px"><span class="game-node-type">${node.node_type==='start'?'起点':node.node_type==='success'?'成功':node.node_type==='failure'?'失败':'节点'}</span><strong>${escapeHtml(node.title)}</strong><small>${node.duration_seconds}s · ${escapeHtml(node.status)}</small></button>`).join('')}</div>`; }
async function gameDetail(id: string, initial?: Game, retry=0) { if(active!=='interactiveGame') return; const main=document.querySelector('main'); if(!main)return; let game=initial; try { const response=await fetch(`${API_BASE_URL}/games/${id}`); if(response.ok) game=gameFromApi(await response.json() as ApiGame); } catch(error) { if(!game) { toast('游戏详情加载失败'); console.error(error); return; } } if(!game)return; if((game.nodes||[]).length===0&&retry<6){ main.innerHTML=gameDetailMarkup(game); setTimeout(()=>gameDetail(id,game,retry+1),1000); return; } main.innerHTML=gameDetailMarkup(game); bindGameEditor(game); }
function bindGameEditor(game: Game) { document.querySelector('#game-back')?.addEventListener('click',()=>{render();void loadInteractiveGames()}); document.querySelector('#game-refresh')?.addEventListener('click',()=>void gameDetail(game.id)); document.querySelector('#game-add-edge')?.addEventListener('click',()=>openEdgeForm(game)); document.querySelectorAll<HTMLElement>('[data-game-node]').forEach(element=>element.addEventListener('click',()=>selectGameNode(game,element.dataset.gameNode!))); document.querySelectorAll<HTMLElement>('[data-game-edge]').forEach(element=>element.addEventListener('click',()=>selectGameEdge(game,element.dataset.gameEdge!))); }
function selectGameNode(game: Game, nodeId: string) { const node=game.nodes?.find(item=>item.id===nodeId); const inspector=document.querySelector('#game-inspector'); if(!node||!inspector)return; inspector.innerHTML=`<div class="inspector-head"><div><div class="eyebrow">${ui('gameNode')}</div><h2>${escapeHtml(node.title)}</h2></div><span class="status ${node.status==='生成中'?'running':''}">${escapeHtml(node.status)}</span></div><label>节点标题<input id="node-title" value="${escapeHtml(node.title)}" /></label><label>原始文本<textarea id="node-original" rows="4">${escapeHtml(node.original_text)}</textarea></label><label>视频 Prompt<textarea id="node-prompt" rows="7">${escapeHtml(node.prompt)}</textarea></label><label>视频时长（秒）<input id="node-duration" type="number" min="1" value="${node.duration_seconds}" /></label><label>视频 URL<input id="node-video-url" value="${escapeHtml(node.video_url||'')}" placeholder="生成后回填远程视频 URL" /></label><div class="inspector-actions"><button class="ghost" id="node-save">${ui('saveChanges')}</button><button class="primary" id="node-generate">${ui('generateNodeVideo')}</button></div><div class="history-list"><h3>视频历史</h3>${(node.video_history||[]).map(video=>`<div>${escapeHtml(video.generated_at||'')} · ${escapeHtml(video.url||'等待生成')}</div>`).join('')||'<p>暂无历史视频</p>'}</div>`; document.querySelector('#node-save')?.addEventListener('click',async()=>{await updateGameNode(game,nodeId,{title:(document.querySelector('#node-title') as HTMLInputElement).value,original_text:(document.querySelector('#node-original') as HTMLTextAreaElement).value,prompt:(document.querySelector('#node-prompt') as HTMLTextAreaElement).value,duration_seconds:Number((document.querySelector('#node-duration') as HTMLInputElement).value),video_url:(document.querySelector('#node-video-url') as HTMLInputElement).value||null})}); document.querySelector('#node-generate')?.addEventListener('click',async()=>{const response=await fetch(`${API_BASE_URL}/games/${game.id}/nodes/${nodeId}/video`,{method:'POST'});if(response.ok){toast('节点视频任务已创建');setTimeout(()=>gameDetail(game.id),700)}else toast('节点视频任务创建失败')}); }
function selectGameEdge(game: Game, edgeId: string) { const edge=game.edges?.find(item=>item.id===edgeId); const inspector=document.querySelector('#game-inspector'); if(!edge||!inspector)return; inspector.innerHTML=`<div class="inspector-head"><div><div class="eyebrow">${ui('gameEdge')}</div><h2>选项配置</h2></div></div><label>选项文案<input id="edge-option" value="${escapeHtml(edge.option_text)}" /></label><label>目标节点<select id="edge-target">${(game.nodes||[]).map(node=>`<option value="${node.id}" ${node.id===edge.target_node_id?'selected':''}>${escapeHtml(node.title)}</option>`).join('')}</select></label><label>排序<input id="edge-order" type="number" min="1" value="${edge.sort_order}" /></label><div class="inspector-actions"><button class="ghost" id="edge-save">${ui('saveChanges')}</button><button class="danger-button" id="edge-delete">${ui('deleteChoice')}</button></div>`; document.querySelector('#edge-save')?.addEventListener('click',async()=>{const response=await fetch(`${API_BASE_URL}/games/${game.id}/edges/${edge.id}`,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({option_text:(document.querySelector('#edge-option') as HTMLInputElement).value,target_node_id:(document.querySelector('#edge-target') as HTMLSelectElement).value,sort_order:Number((document.querySelector('#edge-order') as HTMLInputElement).value)})});if(response.ok){toast('选项已保存');await gameDetail(game.id)}else toast('选项保存失败')}); document.querySelector('#edge-delete')?.addEventListener('click',async()=>{if(!window.confirm('确认删除这个选项？'))return;const response=await fetch(`${API_BASE_URL}/games/${game.id}/edges/${edge.id}`,{method:'DELETE'});if(response.ok){toast('选项已删除');await gameDetail(game.id)}else toast('选项删除失败')}); }
function openEdgeForm(game: Game) { const inspector=document.querySelector('#game-inspector'); if(!inspector)return; const nodes=game.nodes||[]; inspector.innerHTML=`<div class="inspector-head"><div><div class="eyebrow">${ui('gameEdge')}</div><h2>新增选择</h2></div></div><label>来源节点<select id="new-edge-source">${nodes.map(node=>`<option value="${node.id}">${escapeHtml(node.title)}</option>`).join('')}</select></label><label>目标节点<select id="new-edge-target">${nodes.map(node=>`<option value="${node.id}">${escapeHtml(node.title)}</option>`).join('')}</select></label><label>选项文案<input id="new-edge-option" placeholder="例如：相信她的话" /></label><div class="inspector-actions"><button class="ghost" id="new-edge-cancel">取消</button><button class="primary" id="new-edge-save">${ui('saveChanges')}</button></div>`; document.querySelector('#new-edge-cancel')?.addEventListener('click',()=>selectGameNode(game,nodes[0]?.id||'')); document.querySelector('#new-edge-save')?.addEventListener('click',async()=>{const option=(document.querySelector('#new-edge-option') as HTMLInputElement).value.trim();if(!option){toast('请填写选项文案');return;}const response=await fetch(`${API_BASE_URL}/games/${game.id}/edges`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({source_node_id:(document.querySelector('#new-edge-source') as HTMLSelectElement).value,target_node_id:(document.querySelector('#new-edge-target') as HTMLSelectElement).value,option_text:option,sort_order:1})});if(response.ok){toast('选项已新增');await gameDetail(game.id)}else toast('选项新增失败')}); }
async function updateGameNode(game: Game, nodeId: string, payload: Record<string, unknown>) { const response=await fetch(`${API_BASE_URL}/games/${game.id}/nodes/${nodeId}`,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)}); if(response.ok){toast('节点已保存');await gameDetail(game.id)}else toast('节点保存失败'); }
function projectFromApi(p: ApiProject): Project { const assets=p.assets||[]; return { id:p.id, name:p.name, status:p.status, ratio:p.ratio, style:p.style, theme:p.theme, createdAt:p.created_at?.slice(0,16).replace('T',' ')||'刚刚', scenes:p.shots?.length||0, characters:assets.filter(a=>a.type==='character').length, locations:assets.filter(a=>a.type==='scene').length, props:assets.filter(a=>a.type==='prop').length }; }
function projectCard(p: Project) { return `<article class="project-card" data-project="${p.id}"><div class="card-top"><h2>${p.name}</h2><span class="status ${p.status==='生成中'?'running':''}">${p.status==='生成中'?'◌ ':''}${statusLabel(p.status)}</span><div class="tags"><span>${p.ratio}</span><span>${p.style}</span><span>${p.theme}</span></div></div><div class="metrics"><div><strong>${p.scenes}</strong><small>${locale==='en'?'Shots':'分镜'}</small></div><div><strong>${p.characters}</strong><small>${locale==='en'?'Roles':'角色'}</small></div><div><strong>${p.locations}</strong><small>${locale==='en'?'Scenes':'场景'}</small></div><div><strong>${p.props}</strong><small>${locale==='en'?'Props':'道具'}</small></div></div><div class="card-foot">${p.createdAt}<span>›</span></div></article>`; }
function settingsPage() { return `<header><div><div class="eyebrow">${ui('settingsEyebrow')}</div><h1>${ui('settingsTitle')}</h1><p>${ui('settingsDescription')}</p></div></header><section class="settings-grid"><div class="settings-card"><div class="setting-icon">文</div><div><h2>${ui('languageModel')}</h2><p>${ui('languageModelDescription')}</p></div><label>${locale==='en'?'Model name':'模型名称'}<input value="doubao-seed" /></label><label>Endpoint<input placeholder="https://ark.cn-beijing.volces.com/api/v3" /></label><label>API Key<input type="password" placeholder="sk-••••••••••••" /></label><button class="primary wide">${ui('saveLanguage')}</button></div><div class="settings-card"><div class="setting-icon purple">✧</div><div><h2>${ui('multimodalModel')}</h2><p>${ui('multimodalModelDescription')}</p></div><label>${locale==='en'?'Model name':'模型名称'}<input value="doubao-seeddream" /></label><label>Endpoint<input placeholder="https://ark.cn-beijing.volces.com/api/v3" /></label><label>API Key<input type="password" placeholder="sk-••••••••••••" /></label><button class="primary wide">${ui('saveMultimodal')}</button></div></section>`; }
function emptyPage() { const item=nav.find(n=>n[1]===active); const isInteractiveGame=active==='interactiveGame'; return `<div class="empty"><div class="empty-icon">${item?.[0]||'✦'}</div><h1>${navLabel(active)}</h1><p>${isInteractiveGame?ui('interactiveGameDescription'):ui('emptyDescription')}</p>${isInteractiveGame?'':`<button class="primary" data-nav="drama">${ui('enterDrama')}</button>`}</div>`; }
function updateSidebarToggle() { const aside=document.querySelector('aside'); const button=document.querySelector<HTMLButtonElement>('#sidebar-toggle'); const label=sidebarCollapsed?ui('expandSidebar'):ui('collapseSidebar'); aside?.classList.toggle('collapsed',sidebarCollapsed); if(button){button.textContent=sidebarCollapsed?'›':'‹';button.title=label;button.setAttribute('aria-label',label);button.setAttribute('aria-pressed',String(sidebarCollapsed));} }
function toggleSidebar() { sidebarCollapsed=!sidebarCollapsed; localStorage.setItem('sidebarCollapsed',String(sidebarCollapsed)); updateSidebarToggle(); }
function toggleTheme() { darkMode=!darkMode; localStorage.setItem('theme',darkMode?'dark':'light'); applyTheme(); render(); }
function toggleLanguage() { locale=locale==='zh'?'en':'zh'; localStorage.setItem('locale',locale); render(); }
function bind() { document.querySelectorAll<HTMLElement>('[data-nav]').forEach(el=>el.onclick=()=>{active=el.dataset.nav||'drama';render()}); document.querySelector('#new-project')?.addEventListener('click',()=>openModal()); document.querySelector('#new-game')?.addEventListener('click',openGameModal); document.querySelector('#new-game-empty')?.addEventListener('click',openGameModal); document.querySelector('#refresh-games')?.addEventListener('click',()=>void loadInteractiveGames()); document.querySelector('#sidebar-toggle')?.addEventListener('click',toggleSidebar); document.querySelector('#theme-toggle')?.addEventListener('click',toggleTheme); document.querySelector('#language-toggle')?.addEventListener('click',toggleLanguage); document.querySelectorAll<HTMLElement>('[data-project]').forEach(el=>el.onclick=()=>detail(el.dataset.project!)); document.querySelectorAll<HTMLElement>('[data-game]').forEach(el=>el.onclick=()=>void gameDetail(el.dataset.game!)); }
function openModal() { const modal=document.createElement('div'); modal.className='modal-backdrop'; modal.innerHTML=`<div class="modal"><button class="close">×</button><div class="modal-head"><div class="eyebrow">PROJECT / NEW</div><h2>新建短剧</h2><p>先上传或粘贴剧本内容，再补充短剧的基础配置。项目会立即创建，分镜会在后台提取并回填。</p></div><div class="stepper"><span class="current">1 文本来源</span><span>2 基础配置</span></div><label>项目名称 <em>*</em><input id="project-name" placeholder="建议使用书名 / 剧名 + 集数 / 部分来命名" /></label><label>剧本内容 <em>*</em><textarea id="script" placeholder="请将小说、剧本等文本内容粘贴到此处..." rows="7"></textarea><div class="hint">剧本文本不少于 10 个字，创建后会异步拆解为分镜、角色、场景和道具。</div><div class="modal-actions"><button class="ghost close-action">取消</button><button class="primary" id="create">创建并进入详情</button></div></div>`; document.body.append(modal); const close=()=>modal.remove(); modal.querySelectorAll('.close,.close-action').forEach(x=>x.addEventListener('click',close)); modal.querySelector('#create')?.addEventListener('click',async()=>{ const name=(modal.querySelector('#project-name') as HTMLInputElement).value.trim()||'未命名短剧'; const script=(modal.querySelector('#script') as HTMLTextAreaElement).value.trim(); if(script.length<10){toast('剧本文本不少于 10 个字');return;} const button=modal.querySelector('#create') as HTMLButtonElement; button.disabled=true; button.textContent='创建中…'; try { const response=await fetch(`${API_BASE_URL}/projects`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name,script,ratio:'9:16',style:'真人风格',theme:'都市',language_model:'doubao-seed',multimodal_model:'doubao-seeddream'})}); if(!response.ok) throw new Error(`HTTP ${response.status}`); const project=await response.json() as ApiProject; projects.unshift(projectFromApi(project)); close(); detail(project.id,project.name); } catch(error) { button.disabled=false; button.textContent='创建并进入详情'; toast('创建失败，请确认后端已启动'); console.error(error); } }); }
function detail(id: string, name?: string) { const project=projects.find(p=>p.id===id); document.querySelector('main')!.innerHTML=`<div class="detail"><button class="back" id="back">← 返回项目列表</button><header><div><div class="eyebrow">短剧项目 / ${name||project?.name||'金丝雀'}</div><h1>${name||project?.name||'金丝雀'}</h1><p>项目正在后台生成结构化素材，完成后可逐项生成图片和视频。</p></div><button class="primary" id="generate-video">▣ 生成所有视频</button></header><div class="detail-grid"><section class="panel episode-panel"><div class="panel-title"><h2>剧集 / 分镜</h2><button class="ghost">＋ 新增剧集</button></div>${['第1集','第2集','第3集'].map((x,i)=>`<div class="episode"><b>${x}</b><span>${i===0?'1':'0'} 条分镜　⌄</span>${i===0?'<div class="shot selected"><b>#1</b><span class="status running">生成中</span><p>正在提取分镜脚本与基础组成元素...</p></div>':''}</div>`).join('')}</section><section class="panel editor"><div class="panel-title"><div><h2>分镜编辑</h2><p>第1集 · 当前第1条</p></div><button class="primary" id="generate-shot">生成视频</button></div><label>分镜标题<input value="森林中的第一束光" /></label><label>分镜文本<textarea rows="5">${name||'金丝雀'}在森林深处醒来，阳光穿过树叶洒下金色光斑。镜头缓慢推进，鸟儿展开翅膀。</textarea></label><div class="asset-section"><div class="section-title"><h3>基础组成元素</h3><button class="ghost" id="generate-assets">批量生成图片</button></div><div class="asset-tabs"><button class="tab active">角色</button><button class="tab">场景</button><button class="tab">道具</button></div><div class="asset-row"><div class="asset-thumb">◌</div><div><b>金丝雀</b><span>角色 · 基础形态</span><p>人形金丝雀，金色羽毛，温柔而坚定的眼神</p></div><button class="small-btn">生成图片</button></div><div class="asset-row"><div class="asset-thumb green">✦</div><div><b>森林橡树枝桠木</b><span>场景 · 默认形态</span><p>阳光穿过茂密树冠，空气中有微小尘埃</p></div><button class="small-btn">生成图片</button></div></div></section><section class="panel preview"><h2>视频预览</h2><div class="video-placeholder"><div>✦</div><span>生成视频后将在这里预览</span></div><h3>视频生成 Prompt</h3><div class="prompt-box">场景：森林橡树枝桠木<br/>角色：金丝雀（基础形态）<br/>风格：2D动漫风 · 光线：强光暖调<br/>镜头：中景，平视固定镜头，持续 10s</div></section></div></div>`; document.querySelector('#back')?.addEventListener('click',render); document.querySelector('#generate-video')?.addEventListener('click',()=>toast('视频生成任务已创建，后台处理中')); document.querySelector('#generate-shot')?.addEventListener('click',()=>toast('分镜视频任务已创建')); document.querySelector('#generate-assets')?.addEventListener('click',()=>toast('已创建 2 个图片生成任务')); }

type DramaAssetKind = 'character' | 'scene' | 'prop';
type DramaViewState = { projectId: string | null; shotId: string | null; assetPanel: DramaAssetKind | null; videoUrl: string | null };
const dramaViewState: DramaViewState = { projectId: null, shotId: null, assetPanel: null, videoUrl: null };

function dramaKindLabel(kind: string) { return ({ character: '角色', scene: '场景', prop: '道具' } as Record<string, string>)[kind] || kind; }
function dramaStatusClass(status: string) { return status === '生成中' ? 'running' : status === '生成失败' ? 'failed' : status === '生成成功' ? 'success' : ''; }
function dramaStatusText(status: string) { return status || '未生成'; }
function dramaTime(value?: string) { return value ? value.slice(0, 16).replace('T', ' ') : '刚刚'; }
function dramaAssets(project: ApiProject) { return project.assets || []; }
function dramaShots(project: ApiProject) { return project.shots || []; }
function dramaSelectedShot(project: ApiProject) { const shots = dramaShots(project); return shots.find(shot => shot.id === dramaViewState.shotId) || shots[0]; }

function dramaAssetCard(project: ApiProject, asset: DramaAsset) {
  const image = asset.image_url ? `<img src="${escapeHtml(asset.image_url)}" alt="${escapeHtml(asset.name)}" />` : `<div class="drama-asset-placeholder">${asset.type === 'character' ? '♙' : asset.type === 'scene' ? '✦' : '◆'}</div>`;
  return `<article class="drama-asset-card"><div class="drama-asset-image">${image}</div><div class="drama-asset-body"><div class="drama-asset-heading"><div><h3>${escapeHtml(asset.name)}</h3><span>${dramaKindLabel(asset.type)} · ${escapeHtml(asset.id.slice(-8))}</span></div><span class="status ${dramaStatusClass(asset.status)}">${escapeHtml(dramaStatusText(asset.status))}</span></div><p>${escapeHtml(asset.prompt || '等待生成素材提示词')}</p><div class="drama-asset-actions"><button class="small-btn" data-drama-generate-asset="${asset.id}">${asset.status === '生成中' ? '生成中…' : '生成图片'}</button><button class="ghost compact" data-drama-edit-asset="${asset.id}">编辑</button></div></div></article>`;
}

function dramaAssetDrawer(project: ApiProject) {
  const kind = dramaViewState.assetPanel || 'character';
  const assets = dramaAssets(project).filter(asset => asset.type === kind);
  return `<div class="drama-sheet-backdrop" data-drama-close-sheet><aside class="drama-asset-sheet" onclick="event.stopPropagation()"><div class="drama-sheet-head"><div><div class="eyebrow">素材库 / ${dramaKindLabel(kind)}</div><h2>${dramaKindLabel(kind)}素材 <span class="sheet-badge">${assets.filter(asset => asset.status === '生成成功').length} 已完成</span></h2><p>当前共 ${assets.length} 个素材，可继续编辑或生成图片。</p></div><button class="close sheet-close" data-drama-close-sheet>×</button></div><div class="drama-sheet-tabs">${(['character', 'scene', 'prop'] as DramaAssetKind[]).map(item => `<button class="${item === kind ? 'active' : ''}" data-drama-asset-tab="${item}">${dramaKindLabel(item)} <small>${dramaAssets(project).filter(asset => asset.type === item).length}</small></button>`).join('')}</div><div class="drama-sheet-toolbar"><button class="primary" data-drama-generate-all-assets>✦ 生成全部图片</button><button class="ghost" data-drama-copy-public>▣ 公共提示词</button><button class="ghost" data-drama-refresh>↻ 刷新</button></div><div class="drama-sheet-list">${assets.length ? assets.map(asset => dramaAssetCard(project, asset)).join('') : `<div class="drama-sheet-empty"><div class="empty-icon">${kind === 'character' ? '♙' : kind === 'scene' ? '✦' : '◆'}</div><p>还没有${dramaKindLabel(kind)}素材</p></div>`}</div></aside></div>`;
}

function dramaDetailMarkup(project: ApiProject) {
  const shots = dramaShots(project);
  const episodes = project.episodes || [];
  const shot = dramaSelectedShot(project);
  const history = shot?.historical_videos || [];
  const selectedVideo = dramaViewState.videoUrl !== null ? dramaViewState.videoUrl : history[history.length - 1]?.url;
  const allAssets = dramaAssets(project);
  return `<div class="drama-detail"><div class="drama-detail-toolbar"><button class="back" id="drama-back">← 返回</button><div class="drama-project-field"><span>项目名称</span><strong>${escapeHtml(project.name)}</strong></div><div class="drama-config-field"><span>语言模型</span><strong>${escapeHtml(project.language_model || 'doubao-seed')}</strong></div><div class="drama-config-field"><span>图像模型</span><strong>${escapeHtml(project.multimodal_model || 'doubao-seeddream')}</strong></div><div class="drama-config-field ratio"><span>基础图片比例</span><strong>${escapeHtml(project.ratio || '9:16')}</strong></div></div><div class="drama-detail-actions"><button class="ghost" data-drama-copy-public>恢复原始生成结果</button><button class="ghost" data-drama-copy-public>视频公共提示词</button><button class="ghost" id="drama-generate-all-prompts">✣ 批量生成提示词</button><button class="primary" id="drama-generate-all-videos">▣ 生成所有视频</button></div><div class="drama-workspace-grid"><section class="panel drama-episode-panel"><div class="panel-title"><div><h2>剧集 / 分镜</h2><p>${episodes.length} 集 · ${shots.length} 条分镜</p></div><button class="ghost compact" id="drama-add-episode">＋ 新增剧集</button></div><div class="drama-episode-list">${episodes.length ? episodes.map(episode => { const episodeShots = shots.filter(item => item.episode_id === episode.id || item.episode_name === episode.title); return `<div class="drama-episode-block"><div class="drama-episode-head"><div><strong>${escapeHtml(episode.title)}</strong><small>${episodeShots.length} 条分镜</small></div><span>⌃</span></div>${episodeShots.map(item => `<button class="drama-shot-nav ${item.id === shot?.id ? 'selected' : ''}" data-drama-shot="${item.id}"><div><b>#${item.shot_index || 1}</b><span class="status ${dramaStatusClass(item.status)}">${escapeHtml(dramaStatusText(item.status))}</span></div><p>${escapeHtml(item.original_text || item.title)}</p></button>`).join('')}</div>`; }).join('') : `<div class="drama-generating"><div class="empty-icon">◌</div><p>分镜正在后台提取，请稍候…</p></div>`}</div></section><section class="panel drama-shot-editor">${shot ? `<div class="panel-title"><div><h2>分镜编辑</h2><p>${escapeHtml(shot.episode_name || '第1集')} · 当前第 ${shot.shot_index || 1} 条</p></div><button class="primary" id="drama-generate-shot-video">▣ 生成视频</button></div><label>分镜标题<input id="drama-shot-title" value="${escapeHtml(shot.title)}" /></label><label>分镜文本<textarea id="drama-shot-original" rows="4">${escapeHtml(shot.original_text)}</textarea></label><div class="drama-reference-panel"><div class="section-title"><div><h3>参考图</h3><p>从角色 / 场景 / 道具中选择当前分镜使用的素材。</p></div><div class="drama-quick-assets">${(['character', 'scene', 'prop'] as DramaAssetKind[]).map(kind => `<button class="ghost compact" data-drama-open-assets="${kind}">${dramaKindLabel(kind)} ${allAssets.filter(asset => asset.type === kind).length}</button>`).join('')}</div></div><div class="drama-reference-grid">${allAssets.slice(0, 6).map(asset => `<button class="drama-reference-card" data-drama-open-assets="${asset.type}"><span class="drama-reference-thumb">${asset.image_url ? `<img src="${escapeHtml(asset.image_url)}" alt="" />` : '＋'}</span><span><b>${escapeHtml(asset.name)}</b><small>${dramaKindLabel(asset.type)} · ${escapeHtml(asset.status)}</small></span></button>`).join('') || '<p class="muted">分镜拆解完成后，这里会出现角色、场景和道具。</p>'}</div></div><div class="drama-prompt-panel"><div class="section-title"><div><h3>提示词</h3><p>由分镜文本和基础组成元素融合生成，可手动修改。</p></div><div><button class="ghost compact" id="drama-generate-shot-prompt">✣ 生成提示词</button><button class="ghost compact" id="drama-copy-shot-prompt">▣ 复制</button></div></div><textarea id="drama-shot-prompt" rows="9" placeholder="点击生成提示词">${escapeHtml(shot.prompt || '')}</textarea></div><div class="drama-params"><div><span>时长</span><strong>10s</strong></div><div><span>画幅</span><strong>${escapeHtml(project.ratio || '9:16')}</strong></div><button class="ghost" id="drama-save-shot">保存分镜修改</button></div>` : `<div class="drama-generating large"><div class="empty-icon">◌</div><h3>分镜编辑</h3><p>等待剧本拆解完成后，选择一个分镜开始编辑。</p></div>`}</section><section class="panel drama-video-panel"><div class="panel-title"><div><h2>视频预览</h2><p>${shot ? `${history.length} 个历史版本` : '等待分镜'}</p></div><span class="status ${dramaStatusClass(shot?.status || '')}">${escapeHtml(shot?.status || '未生成')}</span></div>${selectedVideo ? `<video id="drama-video-player" controls playsinline src="${escapeHtml(selectedVideo)}"></video>` : `<div class="drama-video-placeholder"><div>✦</div><strong>生成视频后将在这里预览</strong><span>每次生成都会保留历史版本，可在下方切换。</span></div>`}<div class="drama-video-history"><div class="section-title"><h3>视频历史</h3><span>${history.length} 个版本</span></div>${history.length ? history.map((video, index) => `<button class="drama-history-item ${video.url === selectedVideo ? 'selected' : ''}" data-drama-history-url="${escapeHtml(video.url || '')}"><span>${video.url ? '▶' : '◌'}</span><div><b>版本 ${index + 1}</b><small>${dramaTime(video.generated_at)}</small></div></button>`).join('') : '<p class="muted">暂无历史视频</p>'}</div></section></div>${dramaViewState.assetPanel ? dramaAssetDrawer(project) : ''}</div>`;
}

async function loadDramaProjects() { try { const response = await fetch(`${API_BASE_URL}/projects`); if (!response.ok) return; const remote = await response.json() as ApiProject[]; projects.splice(0, projects.length, ...remote.map(projectFromApi)); if (active === 'drama' && !document.querySelector('.drama-detail')) render(); } catch (error) { console.warn('短剧列表加载失败', error); } }
async function loadDramaDetail(id: string, retry = 0) { const main = document.querySelector('main'); if (!main) return; dramaViewState.projectId = id; try { const response = await fetch(`${API_BASE_URL}/projects/${id}`); if (!response.ok) throw new Error(`HTTP ${response.status}`); const project = await response.json() as ApiProject; main.innerHTML = dramaDetailMarkup(project); bindDramaWorkspace(project); if ((project.shots || []).length === 0 && retry < 12) setTimeout(() => void loadDramaDetail(id, retry + 1), 900); } catch (error) { toast('短剧详情加载失败'); console.error(error); } }
async function dramaPost(path: string) { const response = await fetch(`${API_BASE_URL}${path}`, { method: 'POST' }); if (!response.ok) throw new Error(`HTTP ${response.status}`); return await response.json() as { id: string }; }
async function dramaPollTask(taskId: string) { for (let attempt = 0; attempt < 20; attempt += 1) { const response = await fetch(`${API_BASE_URL}/tasks/${taskId}`); if (response.ok) { const task = await response.json() as { status: string }; if (task.status === '生成成功' || task.status === '生成失败') return task; } await new Promise(resolve => setTimeout(resolve, 500)); } return null; }
async function dramaRunTask(path: string, successMessage: string) { try { const task = await dramaPost(path); if (successMessage) toast(successMessage); void dramaPollTask(task.id).then(() => { if (dramaViewState.projectId) void loadDramaDetail(dramaViewState.projectId); }); } catch (error) { toast('任务创建失败'); console.error(error); } }
function dramaPublicPrompt(project: ApiProject) { return `整体保持${project.style || '真人风格'}，题材为${project.theme || '都市'}，画幅${project.ratio || '9:16'}，角色、场景和道具在所有分镜中保持一致。`; }
function bindDramaWorkspace(project: ApiProject) { document.querySelector('#drama-back')?.addEventListener('click', () => { dramaViewState.projectId = null; dramaViewState.shotId = null; dramaViewState.assetPanel = null; render(); }); document.querySelectorAll<HTMLElement>('[data-drama-shot]').forEach(element => element.addEventListener('click', () => { dramaViewState.shotId = element.dataset.dramaShot || null; dramaViewState.videoUrl = null; void loadDramaDetail(project.id); })); document.querySelectorAll<HTMLElement>('[data-drama-open-assets]').forEach(element => element.addEventListener('click', () => { dramaViewState.assetPanel = (element.dataset.dramaOpenAssets || 'character') as DramaAssetKind; const main = document.querySelector('main'); if (main) { main.innerHTML = dramaDetailMarkup(project); bindDramaWorkspace(project); } })); document.querySelectorAll<HTMLElement>('[data-drama-asset-tab]').forEach(element => element.addEventListener('click', () => { dramaViewState.assetPanel = element.dataset.dramaAssetTab as DramaAssetKind; const main = document.querySelector('main'); if (main) { main.innerHTML = dramaDetailMarkup(project); bindDramaWorkspace(project); } })); document.querySelectorAll<HTMLElement>('[data-drama-close-sheet]').forEach(element => element.addEventListener('click', () => { dramaViewState.assetPanel = null; const main = document.querySelector('main'); if (main) { main.innerHTML = dramaDetailMarkup(project); bindDramaWorkspace(project); } })); document.querySelectorAll<HTMLElement>('[data-drama-history-url]').forEach(element => element.addEventListener('click', () => { dramaViewState.videoUrl = element.dataset.dramaHistoryUrl || null; const main = document.querySelector('main'); if (main) { main.innerHTML = dramaDetailMarkup(project); bindDramaWorkspace(project); } })); document.querySelectorAll<HTMLElement>('[data-drama-generate-asset]').forEach(element => element.addEventListener('click', () => void dramaRunTask(`/projects/${project.id}/assets/${element.dataset.dramaGenerateAsset}/image`, '素材图片任务已创建'))); document.querySelectorAll<HTMLElement>('[data-drama-edit-asset]').forEach(element => element.addEventListener('click', async () => { const asset = dramaAssets(project).find(item => item.id === element.dataset.dramaEditAsset); if (!asset) return; const name = window.prompt('素材名称', asset.name); if (name === null) return; const prompt = window.prompt('素材提示词', asset.prompt); if (prompt === null) return; const response = await fetch(`${API_BASE_URL}/projects/${project.id}/assets/${asset.id}`, { method: 'PUT', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ name, prompt }) }); if (response.ok) { toast('素材已保存'); void loadDramaDetail(project.id); } else toast('素材保存失败'); })); document.querySelector('[data-drama-generate-all-assets]')?.addEventListener('click', () => { const assets = dramaAssets(project).filter(asset => asset.type === dramaViewState.assetPanel); void Promise.all(assets.map(asset => dramaRunTask(`/projects/${project.id}/assets/${asset.id}/image`, ''))).then(() => toast(`已创建 ${assets.length} 个${dramaKindLabel(dramaViewState.assetPanel || 'prop')}图片任务`)); }); document.querySelector('[data-drama-copy-public]')?.addEventListener('click', async () => { try { await navigator.clipboard.writeText(dramaPublicPrompt(project)); toast('公共提示词已复制'); } catch { toast('公共提示词：' + dramaPublicPrompt(project)); } }); document.querySelector('[data-drama-refresh]')?.addEventListener('click', () => void loadDramaDetail(project.id)); const shot = dramaSelectedShot(project); if (!shot) return; document.querySelector('#drama-save-shot')?.addEventListener('click', async () => { const response = await fetch(`${API_BASE_URL}/projects/${project.id}/shots/${shot.id}`, { method: 'PUT', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ title: (document.querySelector('#drama-shot-title') as HTMLInputElement).value, original_text: (document.querySelector('#drama-shot-original') as HTMLTextAreaElement).value, prompt: (document.querySelector('#drama-shot-prompt') as HTMLTextAreaElement).value }) }); if (response.ok) { toast('分镜修改已保存'); void loadDramaDetail(project.id); } else toast('分镜保存失败'); }); document.querySelector('#drama-generate-shot-prompt')?.addEventListener('click', () => void dramaRunTask(`/projects/${project.id}/shots/${shot.id}/prompt`, '分镜提示词任务已创建')); document.querySelector('#drama-generate-shot-video')?.addEventListener('click', () => void dramaRunTask(`/projects/${project.id}/shots/${shot.id}/video`, '分镜视频任务已创建')); document.querySelector('#drama-copy-shot-prompt')?.addEventListener('click', async () => { const text = (document.querySelector('#drama-shot-prompt') as HTMLTextAreaElement).value; await navigator.clipboard?.writeText(text); toast('分镜提示词已复制'); }); document.querySelector('#drama-generate-all-prompts')?.addEventListener('click', () => { void Promise.all(dramaShots(project).map(item => dramaRunTask(`/projects/${project.id}/shots/${item.id}/prompt`, ''))).then(() => toast('已创建全部分镜提示词任务')); }); document.querySelector('#drama-generate-all-videos')?.addEventListener('click', () => { void Promise.all(dramaShots(project).map(item => dramaRunTask(`/projects/${project.id}/shots/${item.id}/video`, ''))).then(() => toast('已创建全部分镜视频任务')); }); }
function openModernDramaModal() { const modal = document.createElement('div'); modal.className = 'modal-backdrop'; modal.id = 'drama-create-modal'; modal.innerHTML = `<div class="modal drama-create-modal"><button class="close" data-drama-modal-close>×</button><div class="modal-head"><div class="eyebrow">DRAMA PROJECT / NEW</div><h2>新建短剧</h2><p>先上传或粘贴剧本内容，再补充短剧的基础配置。项目会立即创建，分镜会在后台提取并回填；素材图片在提示词确认后手动生成。</p></div><div class="drama-create-stepper"><span class="active" data-step-label="1">1 文本来源</span><span data-step-label="2">2 基础配置</span></div><section id="drama-create-step-1"><h3>选择文本来源</h3><div class="drama-source-tabs"><label><input type="file" id="drama-file" accept=".txt,.md,.text" />⌃ 上传文件</label><button class="active" id="drama-paste-tab">▣ 粘贴文本</button></div><label>粘贴文本内容 <span id="drama-char-count">0 字</span><textarea id="drama-script" rows="11" placeholder="请将小说、剧本等文本内容粘贴到此处..."></textarea><div class="hint">剧本文本不少于 10 个字，创建后会异步拆解为分镜、角色、场景和道具。</div><div class="modal-actions"><button class="ghost" data-drama-modal-close>取消</button><button class="primary" id="drama-next">下一步 →</button></div></section><section id="drama-create-step-2" hidden><h3>短剧基础配置</h3><label>项目名称 <em>*</em><input id="drama-name" placeholder="建议使用书名 / 剧名 + 集数 / 部分命名" /></label><div class="form-grid"><label>基础视频比例<select id="drama-ratio"><option selected>9:16</option><option>16:9</option></select></label><label>视频风格<select id="drama-style"><option selected>真人风格</option><option>2D动漫风</option><option>3D动漫风</option></select></label><label>叙述背景主题<select id="drama-theme"><option selected>都市</option><option>悬疑</option><option>科幻</option><option>古风</option><option>玄幻</option></select></label><label>语言模型<select id="drama-language-model"><option selected>doubao-seed</option><option>gpt-4o-mini</option></select></label><label>图像 / 视频模型<select id="drama-multimodal-model"><option selected>doubao-seeddream</option><option>gpt-image-1</option></select></label></div><div class="modal-actions"><button class="ghost" id="drama-prev">← 上一步</button><button class="ghost" data-drama-modal-close>取消</button><button class="primary" id="drama-create">创建项目</button></div></section></div>`; document.body.append(modal); const close = () => modal.remove(); modal.querySelectorAll<HTMLElement>('[data-drama-modal-close]').forEach(element => element.addEventListener('click', close)); const script = modal.querySelector<HTMLTextAreaElement>('#drama-script')!; const count = modal.querySelector('#drama-char-count')!; script.addEventListener('input', () => { count.textContent = `${script.value.length} 字`; }); modal.querySelector<HTMLInputElement>('#drama-file')?.addEventListener('change', async event => { const file = (event.target as HTMLInputElement).files?.[0]; if (file) { script.value = await file.text(); script.dispatchEvent(new Event('input')); } }); modal.querySelector('#drama-next')?.addEventListener('click', () => { if (script.value.trim().length < 10) { toast('剧本文本不少于 10 个字'); return; } (modal.querySelector('#drama-create-step-1') as HTMLElement).hidden = true; (modal.querySelector('#drama-create-step-2') as HTMLElement).hidden = false; modal.querySelector('[data-step-label="1"]')?.classList.remove('active'); modal.querySelector('[data-step-label="2"]')?.classList.add('active'); }); modal.querySelector('#drama-prev')?.addEventListener('click', () => { (modal.querySelector('#drama-create-step-1') as HTMLElement).hidden = false; (modal.querySelector('#drama-create-step-2') as HTMLElement).hidden = true; modal.querySelector('[data-step-label="1"]')?.classList.add('active'); modal.querySelector('[data-step-label="2"]')?.classList.remove('active'); }); modal.querySelector('#drama-create')?.addEventListener('click', async () => { const value = (id: string) => (modal.querySelector(`#${id}`) as HTMLInputElement | HTMLSelectElement).value; const name = value('drama-name').trim(); if (!name) { toast('请填写项目名称'); return; } const button = modal.querySelector<HTMLButtonElement>('#drama-create')!; button.disabled = true; button.textContent = '创建中…'; try { const response = await fetch(`${API_BASE_URL}/projects`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ name, script: script.value.trim(), ratio: value('drama-ratio'), style: value('drama-style'), theme: value('drama-theme'), language_model: value('drama-language-model'), multimodal_model: value('drama-multimodal-model') }) }); if (!response.ok) throw new Error(`HTTP ${response.status}`); const project = await response.json() as ApiProject; projects.unshift(projectFromApi(project)); close(); dramaViewState.shotId = null; dramaViewState.videoUrl = null; void loadDramaDetail(project.id); } catch (error) { button.disabled = false; button.textContent = '创建项目'; toast('创建失败，请确认后端已启动'); console.error(error); } }); }
document.addEventListener('click', event => { const target = event.target as HTMLElement; const newProject = target.closest('#new-project'); const projectCardElement = target.closest<HTMLElement>('[data-project]'); if (newProject || projectCardElement) { event.preventDefault(); event.stopPropagation(); if (newProject) openModernDramaModal(); else if (projectCardElement?.dataset.project) void loadDramaDetail(projectCardElement.dataset.project); } }, true);
document.addEventListener('click', event => { const target = event.target as HTMLElement; const button = target.closest<HTMLButtonElement>('.settings-card .wide'); if (!button) return; event.preventDefault(); event.stopPropagation(); const card = button.closest('.settings-card'); const cards = Array.from(document.querySelectorAll('.settings-card')); const inputs = Array.from(card?.querySelectorAll<HTMLInputElement>('input') || []); const kind = cards.indexOf(card as Element) === 0 ? 'language' : 'multimodal'; void fetch(`${API_BASE_URL}/settings/models`, { method: 'PUT', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ kind, model: inputs[0]?.value.trim(), endpoint: inputs[1]?.value.trim(), api_key: inputs[2]?.value.trim() }) }).then(response => { if (!response.ok) throw new Error(`HTTP ${response.status}`); toast(kind === 'language' ? '语言模型配置已保存' : '多模态模型配置已保存'); }).catch(error => { toast('配置保存失败'); console.error(error); }); }, true);
document.addEventListener('click', event => { const target = event.target instanceof HTMLElement ? event.target : null; const button = target?.closest('[data-drama-copy-public]'); if (!button || !dramaViewState.projectId) return; event.preventDefault(); event.stopPropagation(); void fetch(`${API_BASE_URL}/projects/${dramaViewState.projectId}`).then(response => response.json() as Promise<ApiProject>).then(project => navigator.clipboard.writeText(dramaPublicPrompt(project))).then(() => toast('公共提示词已复制')).catch(() => toast('公共提示词复制失败')); }, true);
document.addEventListener('click', event => { const target = event.target instanceof HTMLElement ? event.target : null; const button = target?.closest('.toolbar .ghost'); if (button && active === 'drama' && !button.id) { event.preventDefault(); event.stopPropagation(); void loadDramaProjects(); } }, true);
document.addEventListener('click', event => { const target = event.target instanceof HTMLElement ? event.target : null; const navButton = target?.closest<HTMLElement>('[data-nav]'); if (!navButton?.dataset.nav) return; event.preventDefault(); event.stopPropagation(); active = navButton.dataset.nav; render(); if (active === 'drama') void loadDramaProjects(); if (active === 'interactiveGame') void loadInteractiveGames(); }, true);
document.addEventListener('click', event => { const target = event.target instanceof HTMLElement ? event.target : null; if (!target?.closest('#drama-back')) return; event.preventDefault(); event.stopPropagation(); dramaViewState.projectId = null; dramaViewState.shotId = null; dramaViewState.assetPanel = null; render(); void loadDramaProjects(); }, true);
function escapeHtml(value: unknown) { return String(value??'').replace(/[&<>'"]/g,character=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','\"':'&quot;'}[character]||character)); }
function toast(message:string){const t=document.createElement('div');t.className='toast';t.textContent='✓ '+message;document.body.append(t);setTimeout(()=>t.remove(),2600)}
render();
void loadDramaProjects();
